105		/**
106		 * Documents this component's behavior and responsibilities.
107		 */
108		public <T> void save(T object) {
109	
110			if (object == null) {
111				throw new IllegalArgumentException("The object to save must not be null.");
112			}
113	
114			EntityManager entityManager = jpaUtil.getEntityManager();
115			EntityTransaction transaction = entityManager.getTransaction();
116	
117			try {
118				transaction.begin();
119				entityManager.persist(object);
120				transaction.commit();
121			} catch (RuntimeException e) {
122				if (transaction.isActive()) {
123					transaction.rollback();
124				}
125	
126				throw e;
127			} finally {
128				entityManager.close();
129			}
130		}
