135		public <T> void update(T object) {
136	
137			if (object == null) {
138				throw new IllegalArgumentException("The object to update must not be null.");
139			}
140	
141			EntityManager entityManager = jpaUtil.getEntityManager();
142			EntityTransaction transaction = entityManager.getTransaction();
143	
144			try {
145				transaction.begin();
