159		/**
160		 * Documents this component's behavior and responsibilities.
161		 */
162		public <T> List<T> findByAttribute(
163				Class<T> entityClass,
164				String attribute,
165				Object value
166		) {
167	
168			if (entityClass == null) {
169				throw new IllegalArgumentException("The search class must not be null.");
170			}
171	
172			if (attribute == null || attribute.trim().isEmpty()) {
173				throw new IllegalArgumentException("The search attribute must not be empty.");
174			}
175	
176			EntityManager entityManager = jpaUtil.getEntityManager();
177	
178			try {
179				String parameterName = generateParameterName(attribute);
180	
181				String jpql = "SELECT e FROM "
182						+ entityClass.getSimpleName()
183						+ " e WHERE e."
184						+ attribute
185						+ " = :"
186						+ parameterName;
187	
188				TypedQuery<T> query = entityManager.createQuery(jpql, entityClass);
189				query.setParameter(parameterName, value);
190	
191				return query.getResultList();
192			} finally {
193				entityManager.close();
194			}
195		}
196	
197		/**
198		 * Documents this component's behavior and responsibilities.
199		 */
200		public <T> List<T> findByFields(
201				Class<T> entityClass,
202				Map<String, Object> searchFields
203		) {
204	
205			if (entityClass == null) {
206				throw new IllegalArgumentException("The search class must not be null.");
207			}
208	
209			EntityManager entityManager = jpaUtil.getEntityManager();
210	
211			try {
212				StringBuilder jpql = new StringBuilder();
213	
214				jpql.append("SELECT e FROM ")
215						.append(entityClass.getSimpleName())
216						.append(" e");
217	
218				if (searchFields != null && !searchFields.isEmpty()) {
219					jpql.append(" WHERE ");
220	
221					int index = 0;
222	
223					for (String field : searchFields.keySet()) {
224						if (field == null || field.trim().isEmpty()) {
225							throw new IllegalArgumentException("A search field must not be empty.");
226						}
227	
228						if (index > 0) {
229							jpql.append(" AND ");
230						}
231	
232						String parameterName = generateParameterName(field);
233	
234						jpql.append("e.")
235								.append(field)
236								.append(" = :")
237								.append(parameterName);
238	
239						index++;
240					}
241				}
242	
243				TypedQuery<T> query = entityManager.createQuery(jpql.toString(), entityClass);
244	
245				if (searchFields != null && !searchFields.isEmpty()) {
246					for (Map.Entry<String, Object> entry : searchFields.entrySet()) {
247						String parameterName = generateParameterName(entry.getKey());
248						query.setParameter(parameterName, entry.getValue());
249					}
250				}
251	
252				return query.getResultList();
253			} finally {
254				entityManager.close();
255			}
256		}
257	
258		/**
259		 * Documents this component's behavior and responsibilities.
260		 */
261		public <T> T findById(Class<T> entityClass, Long id) {
262	
263			if (entityClass == null || id == null) {
264				return null;
265			}
266	
267			EntityManager entityManager = jpaUtil.getEntityManager();
268	
269			try {
270				return entityManager.find(entityClass, id);
271			} finally {
272				entityManager.close();
273			}
274		}
275	
276		/**
277		 * Documents this component's behavior and responsibilities.
278		 */
279		private String generateParameterName(String field) {
280			return field.replace(".", "_");
281		}
282	}
