691		private String notifiedStatus;
692	
693		@ManyToOne
694		@JoinColumn(name = "citizen_id", nullable = false)
695		private Citizen destinatario;
696	
697		@ManyToOne
698		@JoinColumn(name = "report_id", nullable = false)
699		private Report report;
