705			/**
706			 * Documents this component's behavior and responsibilities.
707			 */
708		}
709	
710		/**
711		 * Documents this component's behavior and responsibilities.
712		 */
713		Notification(
714				Date sentDate,
715				String message,
716				String notifiedStatus,
717				Citizen destinatario,
718				Report report
719		) {
720			if (sentDate == null) {
721				throw new IllegalArgumentException("Notification date is required.");
722			}
723	
724			if (isBlank(message)) {
725				throw new IllegalArgumentException("Notification message is required.");
726			}
727	
728			if (!isStatusNotifiable(notifiedStatus)) {
729				throw new IllegalArgumentException("The specified status cannot trigger a notification.");
730			}
731	
732			if (destinatario == null) {
733				throw new IllegalArgumentException("Notification recipient is required.");
734			}
735	
736			if (report == null) {
737				throw new IllegalArgumentException("The report associated with the notification is required.");
738			}
739	
740			this.sentDate = new Date(sentDate.getTime());
741			this.message = message.trim();
742			this.notifiedStatus = notifiedStatus.trim();
743			this.destinatario = destinatario;
744			this.report = report;
745		}
