793		/**
794		 * Documents this component's behavior and responsibilities.
795		 */
796		private boolean isStatusNotifiable(String status) {
797			if (isBlank(status)) {
798				return false;
799			}
800	
801			String statusNormalizzato = status.trim();
802	
803			return STATUS_ASSIGNED.equals(statusNormalizzato)
804					|| STATUS_RESOLVED.equals(statusNormalizzato);
805		}
