1931	        private List<Report> filterReportsByRange(
1932	                List<Report> reports,
1933	                Object dateStart,
1934	                Object dateEnd
1935	        ) {
1936	
1937	            List<Report> filtrate = new java.util.ArrayList<>();
1938	
1939	            if (reports == null) {
1940	                return filtrate;
1941	            }
1942	
1943	            Date start = null;
1944	            Date end = null;
1945	
1946	            if (dateStart instanceof Date) {
1947	                start = (Date) dateStart;
1948	            }
1949	
1950	            if (dateEnd instanceof Date) {
1951	                end = (Date) dateEnd;
1952	            }
1953	
1954	            for (Report report : reports) {
1955	                if (report == null) {
1956	                    continue;
1957	                }
1958	
1959	                if (isWithinRange(
1960	                        report.getDateReport(),
1961	                        start,
1962	                        end
1963	                )) {
1964	                    filtrate.add(report);
1965	                }
1966	            }
1967	
1968	            return filtrate;
1969	        }
