1973	         */
1974	        private boolean isWithinRange(
1975	                Date date,
1976	                Date start,
1977	                Date end
1978	        ) {
1979	
1980	            if (date == null) {
1981	                return false;
1982	            }
1983	
1984	            if (start != null && date.before(start)) {
1985	                return false;
1986	            }
1987	
1988	            if (end != null && date.after(end)) {
1989	                return false;
1990	            }
1991	
1992	            return true;
1993	        }
