@Entity
@Table(name = "users")
@Inheritance(strategy = InheritanceType.SINGLE_TABLE)
@DiscriminatorColumn(
		name = "role",
		discriminatorType = DiscriminatorType.STRING,
		length = 30
)
public abstract class User {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	@Column(name = "user_id")
	private Long userId;

	@Column(name = "name", nullable = false, length = 50)
	private String name;

	@Column(name = "lastName", nullable = false, length = 50)
	private String lastName;

	@Column(name = "phone_number", nullable = false, length = 20)
	private String phoneNumber;

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	@Embedded
	@AttributeOverrides({
			@AttributeOverride(
					name = "email",
					column = @Column(
							name = "email",
							nullable = false,
							unique = true,
							length = 100
					)
			),
			@AttributeOverride(
					name = "password",
					column = @Column(
							name = "password",
							nullable = false,
							length = 100
					)
			)
	})
	private Credentials credentials;

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	protected User() {
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	protected User(String name,
	                 String lastName,
	                 String phoneNumber,
	                 String email,
	                 String password) {

		if (isBlank(name)) {
			throw new IllegalArgumentException("First name must not be empty.");
		}

		if (isBlank(lastName)) {
			throw new IllegalArgumentException("Last name must not be empty.");
		}

		if (isBlank(phoneNumber)) {
			throw new IllegalArgumentException("Phone number must not be empty.");
		}

		this.name = name.trim();
		this.lastName = lastName.trim();
		this.phoneNumber = phoneNumber.trim();

		/**
		 * Documents this component's behavior and responsibilities.
		 */
		this.credentials = new Credentials(email, password);
	}

	public Long getUserId() {
		return this.userId;
	}

	public String getName(){
		return this.name;
	}

	public String getLastName(){
		return this.lastName;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private boolean isBlank(String value) {
		return value == null || value.trim().isEmpty();
	}

}package Entity;

import Database.PersistenceService;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Documents this component's behavior and responsibilities.
 */
public class UserService {

	private PersistenceService persistenceService;

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public UserService() {
		this.persistenceService = new PersistenceService();
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public boolean isUserRegistered(Map<String, Object> registrationData) {

		if (registrationData == null) {
			return false;
		}

		return !verifyCredentialsAvailability(registrationData);
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public boolean verifyUserCitizen(Long userId) {

		if (userId == null) {
			return false;
		}

		Citizen citizen = persistenceService.findById(
				Citizen.class,
				userId
		);

		return citizen != null;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public boolean isMunicipalOperator(Long userId) {

		if (userId == null) {
			return false;
		}

		MunicipalOperator operator = persistenceService.findById(
				MunicipalOperator.class,
				userId
		);

		return operator != null;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public Long registerUser(Map<String, Object> registrationData) {

		if (registrationData == null) {
			return null;
		}

		if (isUserRegistered(registrationData)) {
			return null;
		}

		try {
			User user = createUserFromRegistrationData(registrationData);

			if (user == null) {
				return null;
			}

			persistenceService.save(user);

			return user.getUserId();

		} catch (RuntimeException e) {
			System.err.println("[UserService] Error during user registration: "
					+ e.getMessage());
			return null;
		}
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public Map<String, Object> retrieveUserDataByCredentials(Map<String, Object> loginData) {

		if (loginData == null) {
			return null;
		}

		String email = extractString(loginData.get("email"));
		String password = extractString(loginData.get("password"));

		if (isBlank(email) || isBlank(password)) {
			return null;
		}

		/**
		 * Documents this component's behavior and responsibilities.
		 */
		Map<String, Object> searchFields = new HashMap<>();
		searchFields.put("credentials.email", email);
		searchFields.put("credentials.password", password);

		List<User> foundUsers = persistenceService.findByFields(
				User.class,
				searchFields
		);

		if (foundUsers == null || foundUsers.isEmpty()) {
			return null;
		}

		User userAuthenticated = foundUsers.get(0);

		return createUserSessionData(userAuthenticated);
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private boolean verifyCredentialsAvailability(Map<String, Object> registrationData) {

		if (registrationData == null) {
			return false;
		}

		String email = extractString(registrationData.get("email"));

		if (isBlank(email)) {
			return false;
		}

		return !isEmailRegistered(email);
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private boolean isEmailRegistered(String email) {

		if (isBlank(email)) {
			return false;
		}

		Map<String, Object> searchFields = new HashMap<>();
		searchFields.put("credentials.email", email);

		List<User> foundUsers = persistenceService.findByFields(
				User.class,
				searchFields
		);

		return foundUsers != null && !foundUsers.isEmpty();
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private User createUserFromRegistrationData(Map<String, Object> registrationData) {

		if (registrationData == null) {
			return null;
		}

		String name = extractString(registrationData.get("name"));
		String lastName = extractString(registrationData.get("lastName"));
		String phoneNumber = extractString(registrationData.get("phoneNumber"));
		String email = extractString(registrationData.get("email"));
		String password = extractString(registrationData.get("password"));
		String role = extractString(registrationData.get("role"));

		if (isBlank(name)
				|| isBlank(lastName)
				|| isBlank(phoneNumber)
				|| isBlank(email)
				|| isBlank(password)
				|| isBlank(role)) {
			return null;
		}

		/**
		 * Documents this component's behavior and responsibilities.
		 */
		if ("citizen".equalsIgnoreCase(role)
				|| "Citizen".equalsIgnoreCase(role)) {
			return new Citizen(
					name,
					lastName,
					phoneNumber,
					email,
					password
			);
		}

		if ("operator municipal".equalsIgnoreCase(role)
				|| "Municipal Operator".equalsIgnoreCase(role)
				|| "operator_municipal".equalsIgnoreCase(role)
				|| "operator".equalsIgnoreCase(role)) {
			return new MunicipalOperator(
					name,
					lastName,
					phoneNumber,
					email,
					password
			);
		}

		return null;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private Map<String, Object> createUserSessionData(User userAuthenticated) {

		if (userAuthenticated == null || userAuthenticated.getUserId() == null) {
			return null;
		}

		String role = retrieveRoleUser(userAuthenticated);

		if (isBlank(role)) {
			return null;
		}

		Map<String, Object> userSessionData = new HashMap<>();

		userSessionData.put("userId", userAuthenticated.getUserId());
		userSessionData.put("name", userAuthenticated.getName());
		userSessionData.put("lastName", userAuthenticated.getLastName());
		userSessionData.put("role", role);

		return userSessionData;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private String retrieveRoleUser(User userAuthenticated) {

		if (userAuthenticated instanceof Citizen) {
			return "Citizen";
		}

		if (userAuthenticated instanceof MunicipalOperator) {
			return "Municipal Operator";
		}

		return null;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private String extractString(Object value) {

		if (value == null) {
			return null;
		}

		if (value instanceof char[]) {
			return new String((char[]) value);
		}

		return value.toString().trim();
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private boolean isBlank(String value) {
		return value == null || value.trim().isEmpty();
	}
